function positionHolder(ul, holder, clientY){
  const items = [...ul.children].filter(el => el !== holder);
  let before = null;
  for (const el of items){
    const r = el.getBoundingClientRect();
    if (clientY < r.top + r.height / 2){ before = el; break; }
  }
  if (before) {
    if (holder.previousElementSibling !== before && holder !== before)
      ul.insertBefore(holder, before);
  } else if (ul.lastElementChild !== holder) {
    ul.appendChild(holder);
  }
}

