node -e '
const fs=require("fs");
const src=fs.readFileSync("/tmp/app_test.js","utf8");
const m=src.match(/const STEPS = (\[[\s\S]*?\n  \]);/);
const STEPS=eval(m[1]);
if(STEPS.length!==8) throw "steps";
let ok=true;
for(const lists of STEPS){
  if(lists.length!==3) throw "lists";
  for(const items of lists){
    if(items.length!==4) throw "items";
    const types=items.map(x=>x[1]).sort().join("");
    if(types!=="cdis"){ok=false;console.log("bad list types",types,items.map(x=>x[0]));}
  }
}
console.log("data ok:", ok, "—", STEPS.flat().length, "cards,", STEPS.flat().length*4, "options");
// expected initial score
function score(lists){const s={d:0,i:0,s:0,c:0};for(const items of lists){s[items[0][1]]++;s[items[3][1]]--;}return s;}
const init=STEPS.reduce((acc,lists)=>{const sc=score(lists);for(const k in sc)acc[k]+=sc[k];return acc;},{d:0,i:0,s:0,c:0});
console.log("initial-order score:",JSON.stringify(init));
// worst-case bounds: each of 24 cards contributes +1/-1; max per type when every pos0 is that type = 24
console.log("bounds ok (-24..24)");
'

