const WebSocket = require('/home/dp/.npm-global/lib/node_modules/cline/node_modules/ws');
const { spawn } = require('child_process');
const http = require('http');

const chrome = spawn('google-chrome', ['--headless=new','--no-sandbox','--disable-gpu','--remote-debugging-port=9333','about:blank'],
  { stdio: 'ignore' });

function get(url){ return new Promise((res,rej)=>{ http.get(url, r=>{ let d=''; r.on('data',c=>d+=c); r.on('end',()=>res(d)); }).on('error',rej); }); }

async function waitFor(){ for(let i=0;i<50;i++){ try{ const t=await get('http://127.0.0.1:9333/json'); return JSON.parse(t); }catch{ await new Promise(r=>setTimeout(r,200)); } } throw new Error('no chrome'); }

let id=0; const pending=new Map();
function send(ws, method, params={}){ return new Promise((res,rej)=>{ const m=id++; pending.set(m,{res,rej}); ws.send(JSON.stringify({id:m,method,params})); }); }
const events={};
function on(evt, fn){ (events[evt]=events[evt]||[]).push(fn); }

(async () => {
  const list = await waitFor();
  const page = list.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl, { perMessageDeflate: false });
  await new Promise(r => ws.on('open', r));
  ws.on('message', d => {
    const m = JSON.parse(d);
    if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.rej(new Error(m.error.message)) : p.res(m.result); }
    else if (m.method) (events[m.method]||[]).forEach(f=>f(m.params));
  });
  const errors = [];
  on('Runtime.exceptionThrown', p => errors.push(p.exceptionDetails.text + ' ' + (p.exceptionDetails.exception?.description||'')));
  on('Runtime.consoleAPICalled', p => { if (p.type==='error') errors.push(p.args.map(a=>a.value||a.description).join(' ')); });
  await send(ws, 'Runtime.enable');

  const ev = async (expr) => (await send(ws, 'Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })).result.value;

  await ev(`document.title`);
  // navigate
  await send(ws, 'Page.enable');
  const nav = send(ws, 'Page.navigate', { url: 'file:///tmp/disc-pi-pruiv7lj/run/index.html' });
  await new Promise(r => setTimeout(r, 600));
  await nav;
  await new Promise(r => setTimeout(r, 300));

  console.log('title:', await ev(`document.title`));
  console.log('hero visible:', await ev(`!document.querySelector('#startBtn')?.hidden && getComputedStyle(document.querySelector('header.hero')).display !== 'none'`));

  // start test
  await ev(`document.querySelector('#startBtn').click(); true`);
  await new Promise(r => setTimeout(r, 200));
  console.log('app visible after start:', await ev(`!document.querySelector('#app').hidden`));
  console.log('tabs count:', await ev(`document.querySelector('#tabs').children.length`));
  console.log('step1 cards:', await ev(`document.querySelectorAll('#stepPane .card').length`));
  console.log('step1 items:', await ev(`document.querySelectorAll('#stepPane li.item').length`));
  console.log('progress text:', await ev(`document.querySelector('#progressTxt').textContent`));

  // drag item in the first card of step 1: drag first li to bottom (index 0 -> 3)
  const dragged = await ev(`
    (function(){
      const ul = document.querySelector('#stepPane li.item').parentElement;
      const li = ul.querySelector('li.item');
      const r = li.getBoundingClientRect();
      const mk = (t,x,y) => new PointerEvent(t,{bubbles:true,cancelable:true,pointerId:1,pointerType:'touch',clientX:x,clientY:y,button:0});
      ul.dispatchEvent(mk('pointerdown', r.left+10, r.top+10));
      const items=[...ul.querySelectorAll('li.item')]; items.pop();
      const last = items[items.length-1].getBoundingClientRect();
      ul.dispatchEvent(mk('pointermove', r.left+10, last.bottom+5));
      ul.dispatchEvent(mk('pointerup', r.left+10, last.bottom+5));
      return [...ul.querySelectorAll('li.item .text')].map(e=>e.textContent).join(' | ');
    })()
  `);
  console.log('order after drag:', dragged);

  // walk to last step
  for (let i=0;i<7;i++){ await ev(`document.querySelector('#btnNext').click(); true`); }
  await new Promise(r => setTimeout(r, 200));
  console.log('at last step, finish visible:', await ev(`!document.querySelector('#btnFinish').hidden && document.querySelector('#btnNext').hidden`));
  console.log('progress text:', await ev(`document.querySelector('#progressTxt').textContent`));

  // check drag actually recorded: re-check step 1 order preserved after navigation back
  await ev(`document.querySelector('#btnPrev').click(); true`);
  console.log('back to step1, order preserved:', await ev(`[...document.querySelectorAll('#stepPane li.item .text')].map(e=>e.textContent).slice(0,4).join(' | ')`));

  // finish
  await ev(`document.querySelector('#btnNext').click(); true`);
  await ev(`document.querySelector('#btnFinish').click(); true`);
  await new Promise(r => setTimeout(r, 300));
  console.log('results visible:', await ev(`!document.querySelector('#resultsWrap').hidden`));
  console.log('scores html:', await ev(`document.querySelector('#scores').textContent.replace(/\\s+/g,' ')`));
  console.log('desc:', await ev(`document.querySelector('#desc').textContent.trim().slice(0,120)`));
  console.log('chart svg present:', await ev(`!!document.querySelector('#chart svg')`));

  // restart resets order
  await ev(`document.querySelector('#btnRestart').click(); true`);
  await new Promise(r => setTimeout(r, 200));
  console.log('after restart step1 card1 first item:', await ev(`document.querySelector('#stepPane li.item .text').textContent`));
  console.log('console/runtime errors:', errors.length ? errors : 'none');
  chrome.kill(); process.exit(0);
})().catch(e => { console.error('FAIL', e); chrome.kill(); process.exit(1); });
